#!/usr/bin/env python3
"""Pebble virtual machine – stack-based bytecode interpreter."""

import sys


MASK = 0xFFFFFFFFFFFFFFFF
LOW32 = 0x7FFFFFFF
HIGH32 = 0x8000000000000000


def to_i32(n):
    """Reduce *n* to a signed 32-bit integer (two's complement, wrapping)."""
    n &= MASK
    if n & HIGH32:
        n -= 1 << 32
    return n


def parse(program):
    """Return (labels, instructions) from *program* text.

    *labels* maps label name → index into *instructions*.
    Each entry in *instructions* is a tuple (opcode, operand_or_None).
    """
    labels = {}
    instructions = []
    for raw_line in program.splitlines():
        # strip comments
        line = raw_line.split("#", 1)[0].strip()
        if not line:
            continue
        # label?
        if line.endswith(":"):
            labels[line[:-1]] = len(instructions)
            continue
        parts = line.split()
        opcode = parts[0]
        operand = parts[1] if len(parts) > 1 else None
        instructions.append((opcode, operand))
    return labels, instructions


def run(instructions, labels):
    """Execute *instructions* with *labels*. Returns (exit_code, output_lines)."""
    stack = []
    variables = {}
    pc = 0
    call_stack = []  # indices to return to
    output = []

    while pc < len(instructions):
        opcode, operand = instructions[pc]

        if opcode == "HALT":
            return (0, output)

        elif opcode == "PUSH":
            stack.append(to_i32(int(operand)))
            pc += 1

        elif opcode == "POP":
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            stack.pop()
            pc += 1

        elif opcode == "DUP":
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            stack.append(stack[-1])
            pc += 1

        elif opcode == "SWAP":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1

        elif opcode == "ADD":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            stack.append(to_i32(a + b))
            pc += 1

        elif opcode == "SUB":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            stack.append(to_i32(a - b))
            pc += 1

        elif opcode == "MUL":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            stack.append(to_i32(a * b))
            pc += 1

        elif opcode == "DIV":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                print("E02: division by zero")
                return (1, output)
            # truncate toward zero
            stack.append(to_i32(int(a / b)))
            pc += 1

        elif opcode == "MOD":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                print("E02: division by zero")
                return (1, output)
            # Python % follows sign of divisor; we need sign of dividend (a)
            result = a - to_i32(int(a / b)) * b
            stack.append(to_i32(result))
            pc += 1

        elif opcode == "NEG":
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            stack.append(to_i32(-stack[-1]))
            pc += 1

        elif opcode == "EQ":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            stack.append(1 if a == b else 0)
            pc += 1

        elif opcode == "LT":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            stack.append(1 if a < b else 0)
            pc += 1

        elif opcode == "GT":
            if len(stack) < 2:
                print("E01: stack is empty")
                return (1, output)
            b = stack.pop()
            a = stack.pop()
            stack.append(1 if a > b else 0)
            pc += 1

        elif opcode == "NOT":
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            a = stack.pop()
            stack.append(1 if a == 0 else 0)
            pc += 1

        elif opcode == "LOAD":
            var = operand
            if var not in variables:
                print(f"E03: variable is not set")
                return (1, output)
            stack.append(variables[var])
            pc += 1

        elif opcode == "STORE":
            var = operand
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            variables[var] = stack.pop()
            pc += 1

        elif opcode == "JMP":
            label = operand
            if label not in labels:
                print(f"E04: unknown label")
                return (1, output)
            pc = labels[label]

        elif opcode == "JZ":
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            val = stack.pop()
            if val == 0:
                label = operand
                if label not in labels:
                    print(f"E04: unknown label")
                    return (1, output)
                pc = labels[label]
            else:
                pc += 1

        elif opcode == "JNZ":
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            val = stack.pop()
            if val != 0:
                label = operand
                if label not in labels:
                    print(f"E04: unknown label")
                    return (1, output)
                pc = labels[label]
            else:
                pc += 1

        elif opcode == "CALL":
            label = operand
            if label not in labels:
                print(f"E04: unknown label")
                return (1, output)
            call_stack.append(pc + 1)
            pc = labels[label]

        elif opcode == "RET":
            if not call_stack:
                print("E05: no call frame")
                return (1, output)
            pc = call_stack.pop()

        elif opcode == "PRINT":
            if not stack:
                print("E01: stack is empty")
                return (1, output)
            output.append(str(stack.pop()))
            pc += 1

        else:
            print(f"E06: unknown instruction")
            return (1, output)

    # ran off end of program → HALT
    return (0, output)


def main():
    if len(sys.argv) < 2:
        print("Usage: vm.py PROGRAM.pbl", file=sys.stderr)
        sys.exit(1)

    with open(sys.argv[1]) as f:
        program = f.read()

    labels, instructions = parse(program)
    exit_code, output = run(instructions, labels)

    for line in output:
        print(line)

    sys.exit(exit_code)


if __name__ == "__main__":
    main()

